        ImmutableList.of(binder -> {})
    );

    injectorForIndexer = Guice.createInjector(
        ImmutableList.of(
            binder -> binder.bind(IndexerTaskCountStatsProvider.class).toInstance(indexerTaskStatsProvider)
        )
    );
